mapper.select:

where p.shop_code = #{shopCode}

  and p.goods_code like concat('%', #{goodsCode}, '%')


  and p.goods_name like concat('%', #{goodsName}, '%')


  and p.ware_code = #{wareCode}


  and p.position like concat('%', #{position}, '%')

order by p.update_time desc, p.position_id desc


where p.shop_code = #{shopCode}
  and p.goods_code = #{goodsCode}

  and p.position_id != #{excludePositionId}

limit 1

